#!/bin/bash
# AI DISCLAIMER: All of the text in this file was generated by AI.
# G018 box5600g runs, after box3900x's chain (its source node runs on box3900x, so the two must not overlap):
#  1. BP+ replay, all 12 threads, B (.8 native) N N B (.9 native), stressnet_h3103300c restored before each run;
#  2. fastbox heavy and small-tx windows, default threads, 3 rounds, S=.8 against E=.9 (fbm9_window.sh), out9/.
# Blocks from a stock source node on box3900x over the LAN. Marker CHAIN_DOT9M_DONE <ok|FAIL>.
set -u
G=$CTRL/dot9; L=$G/chain_dot9m.log
HIP=${HIP:?the 3900X LAN address}; EXPECT=020744aa54024f2d0c03c68515d98a2060bf01f33e207291c17d733dd5f91c60
BW=$HOME/work/bppall; W=$HOME/work/fastbox; O=$W/out9; SN=$HOME/work/research-artifacts/snapshots
log() { echo "$(date -u +%FT%TZ) $*" >> $L; }
stopsrc() { ssh -n box3900x "bash ~/work/g016/src_node.sh $HIP stop" >> $L 2>&1; }
fail() { log "$*"; stopsrc; log "CHAIN_DOT9M_DONE FAIL"; exit 1; }
log "chain start"
until grep -q CHAIN_DOT9H_DONE $G/chain_dot9h.log 2>/dev/null; do sleep 60; done
grep -q "CHAIN_DOT9H_DONE ok" $G/chain_dot9h.log || { log "box3900x chain failed; not starting"; log "CHAIN_DOT9M_DONE FAIL"; exit 1; }
until ssh -n box5600g "grep -q MP_BUILD_DOT9_DONE $W/mp_build_dot9.log"; do sleep 60; done
ssh -n box5600g "grep -q 'MP_BUILD_DOT9_DONE ok' $W/mp_build_dot9.log" || fail "box5600g build failed"
log "box5600g: $(ssh -n box5600g "grep -E '^[NE]: ' $W/mp_build_dot9.log | tr '\n' ' '")"
ssh -n box3900x "pgrep -u $USER -x monerod" > /dev/null && fail "a monerod runs on box3900x"
ssh -n box3900x "RPC_LAN=1 bash ~/work/g016/src_node.sh $HIP start" >> $L 2>&1 || fail "source node did not start"
run() {  # <name> <binary>
  local name=$1 bin=$2
  ssh -n box5600g "pgrep -u $USER -x monerod" > /dev/null && fail "a monerod runs on box5600g"
  ~/snapshots/snapctl.sh restore box5600g stressnet_h3103300c box3900x >> $L 2>&1 || fail "restore failed before $name"
  sleep 60
  log "start $name"
  ssh -n box5600g "cd $BW && (env SRC=$HIP:28180 EXPECT=$EXPECT END=3103500 setsid nohup bash bpp_run_5600g.sh $name $bin > $name.out 2>&1 < /dev/null &)"
  until ssh -n box5600g "grep -q BPP_RUN_DONE $BW/runs/$name/run.log 2>/dev/null"; do sleep 30; done
  ssh -n box5600g "tail -5 $BW/runs/$name/run.log" >> $L
  ssh -n box5600g "grep -q 'BPP_RUN_DONE end' $BW/runs/$name/run.log && grep -q HASH_OK $BW/runs/$name/run.log" || fail "$name did not end ok"
}
run d9m1_B $W/bin/E/monerod
run d9m1_N $W/bin/N/monerod
run d9m2_N $W/bin/N/monerod
run d9m2_B $W/bin/E/monerod
ssh -n box5600g "python3 -I $BW/dot9_ab.py $BW/runs d9m1_B d9m1_N d9m2_N d9m2_B" >> $L 2>&1
# fastbox: the working DB above is no longer needed; one snapshot on box5600g at a time
ssh -n box5600g "rm -f ~/work/chains/stressnet/testnet/lmdb/data.mdb ~/work/chains/stressnet/testnet/lmdb/lock.mdb; df --output=avail -BG ~ | tail -1" >> $L 2>&1
win() {  # <snapshot> <name> <END> <TIMEOUT> [<extra>]
  local snap=$1 name=$2 end=$3 to=$4 wx="${5:-}"
  ~/snapshots/snapctl.sh put box5600g $snap box3900x >> $L 2>&1 || fail "put $snap"
  log "snapshot $snap on box5600g; free $(ssh -n box5600g "df --output=avail -BG ~ | tail -1")"
  log "start ${name}_default"
  ssh -n box5600g "cd $W && mkdir -p $O && (env PEER=$HIP:28180 PEER_RPC=$HIP:28189 DD=$W/run SNAP=$SN/$snap setsid nohup bash fbm9_window.sh $O/${name}_default $end $to 3 default \"$wx\" > /dev/null 2>&1 < /dev/null &)"
  until ssh -n box5600g "grep -q FBM_WIN_DONE $O/${name}_default.fbm 2>/dev/null"; do sleep 30; done
  ssh -n box5600g "tail -2 $O/${name}_default.fbm; tail -3 $O/${name}_default/summary.txt" >> $L
  ssh -n box5600g "grep -q 'FBM_WIN_DONE 0' $O/${name}_default.fbm && tail -1 $O/${name}_default/summary.txt | grep -qx AB_COMPLETE" || fail "${name}_default did not complete"
  ~/snapshots/snapctl.sh drop box5600g $snap box3900x >> $L 2>&1 || fail "drop $snap"
}
win stressnet_wedge_h3105401 heavy 3105444 1500 "--block-sync-size 5"
win stressnet_h3106400c small 3106800 2400
stopsrc
ssh -n box5600g "rm -rf $W/run; python3 -I $W/kit/fastbox-kit/fb_table.py $O > $O/fb_table.txt 2>&1" >> $L 2>&1
log "CHAIN_DOT9M_DONE ok"
